import java.util.*;

class Solution {
    public int detectCycle(int[] next) {
        if (next.length == 0) return -1;
        int slow = 0, fast = 0;
        while (true) {
            if (next[fast] == -1 || next[next[fast]] == -1) return -1; // no loop
            slow = next[slow];
            fast = next[next[fast]];
            if (slow == fast) break;                 // met inside the loop
        }
        slow = 0;                                    // phase 2: restart from the start
        while (slow != fast) {
            slow = next[slow];
            fast = next[fast];
        }
        return slow;                                 // the loop's entrance
    }
}

