class Solution:
    def detectCycle(self, next: List[int]) -> int:
        if not next: return -1
        s = f = 0
        while f != -1 and next[f] != -1:
            s = next[s]; f = next[next[f]]
            if s == f:
                s = 0
                while s != f: s, f = next[s], next[f]
                return s
        return -1
